import json,glob,os,collections,re,sys
base=os.path.expanduser('~/.claude/projects')
# 1) all projects: mcp playwright / browser tool names
mc=collections.Counter()
for f in glob.glob(base+'/*/**/*.jsonl',recursive=True):
    with open(f,errors='ignore') as fh:
        for l in fh:
            if 'mcp__playwright' not in l and 'mcp__Claude_Browser' not in l and 'claude-in-chrome' not in l: continue
            try:d=json.loads(l)
            except: continue
            cc=(d.get('message') or {}).get('content')
            if not isinstance(cc,list): continue
            for b in cc:
                if isinstance(b,dict) and b.get('type')=='tool_use' and re.match(r'mcp__(playwright|Claude_Browser|claude-in-chrome|remote)',b['name']):
                    mc[(f.split('/')[5][:50],os.path.basename(f)[:8],b['name'])]+=1
for k,v in sorted(mc.items()): print(k,v)
# 2) pages main session: bash commands w/ screenshot
f=glob.glob(base+'/-Users-gabe-Projects-pages/24655582*.jsonl')[0]
bydate=collections.Counter();kinds=collections.Counter()
for l in open(f,errors='ignore'):
    if 'screenshot' not in l and 'playwright' not in l: continue
    try:d=json.loads(l)
    except: continue
    cc=(d.get('message') or {}).get('content')
    if not isinstance(cc,list): continue
    for b in cc:
        if isinstance(b,dict) and b.get('type')=='tool_use' and b['name']=='Bash':
            cmd=b['input'].get('command','')
            ts=d.get('timestamp','')[:10]
            if re.search(r'\.screenshot\(|screenshot\.(cjs|mjs|js)|shot\.cjs|chromium\.launch',cmd): kinds['script-screenshot']+=1;bydate[ts]+=1
            if re.search(r'playwright test',cmd): kinds['playwright test']+=1
            if re.search(r'toHaveScreenshot',cmd): kinds['toHaveScreenshot']+=1
print(kinds,sorted(bydate.items()))

